  function plainLifeText(value){let out=text(value);const replacements=[[/[甲乙丙丁戊己庚辛壬癸木火土金水]\([^)]*\)/g,'나의 기본 성향'],[/비견[·ㆍ]?겁재|비겁/g,'자기주도·동료 성향'],[/식신[·ㆍ]?상관|식상/g,'표현·생산 성향'],[/정재[·ㆍ]?편재|재성/g,'현실·자원 관리 성향'],[/정관[·ㆍ]?편관|관성/g,'책임·규칙 성향'],[/정인[·ㆍ]?편인|인성/g,'학습·검토 성향'],[/신강[·ㆍ]?신약|강약 판정/g,'에너지를 쓰는 방식'],[/용신/g,'균형을 위해 보완할 방향'],[/일간/g,'나의 기본 반응'],[/일지/g,'가까운 관계에서의 생활 반응'],[/십성/g,'생활 역할'],[/원국/g,'타고난 성향 구성'],[/명리(?:학)?/g,'전통 해석']];for(const [pattern,replacement] of replacements)out=out.replace(pattern,replacement);return out}
