  async function api(path,options={}){const res=await fetch(path,{headers:{'Content-Type':'application/json'},...options});const body=await res.json().catch(()=>({ok:false,error:'서버 응답을 읽지 못했습니다.'}));if(!res.ok||body.ok===false)throw new Error(body.error||'요청을 처리하지 못했습니다.');return body.data}
  function parseDate(value){const digits=String(value||'').replace(/\D/g,'');if(digits.length!==8)return null;const y=+digits.slice(0,4),m=+digits.slice(4,6),d=+digits.slice(6,8),dt=new Date(y,m-1,d);return dt.getFullYear()===y&&dt.getMonth()===m-1&&dt.getDate()===d?{year:y,month:m,day:d}:null}
  function parseTime(value){const digits=String(value||'').replace(/\D/g,'');if(!digits)return null;const padded=digits.length<=2?digits.padStart(2,'0')+'00':digits.padStart(4,'0');const hour=+padded.slice(0,2),minute=+padded.slice(2,4);return hour<24&&minute<60?{hour,minute}:null}
  function syncMainInputs(){const form=$('#profileForm'),d=parseDate($('[data-birth-text="main"]')?.value),unknown=form.elements.time_unknown.checked,t=unknown?{hour:0,minute:0}:parseTime($('[data-time-text="main"]')?.value);if(d){form.elements.year.value=d.year;form.elements.month.value=d.month;form.elements.day.value=d.day}if(t){form.elements.hour.value=t.hour;form.elements.minute.value=t.minute}return {d,t,unknown}}
  function validateVisibleForm(form=$('#profileForm')){const {d,t,unknown}=syncMainInputs();$$('.field-error',form).forEach(e=>show(e,false));let target=null,message='';if(!d){const e=$('[data-error-for="main-birth"]');e.textContent='생년월일을 8자리로 정확히 입력해 주세요.';show(e,true);target=$('[data-birth-text="main"]');message=e.textContent}else if(!unknown&&!t){const e=$('[data-error-for="main-time"]');e.textContent='출생시간을 24시간제로 입력하거나 ‘시간을 몰라요’를 선택해 주세요.';show(e,true);target=$('[data-time-text="main"]');message=e.textContent}else if(!form.checkValidity()){target=$(':invalid',form);message='필수 입력값을 확인해 주세요.'}if(target){toast(message);target.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>target.focus({preventScroll:true}),350);return false}return true}
  function mainProfile(){const f=$('#profileForm'),fd=new FormData(f),unknown=f.elements.time_unknown.checked;return {name:String(fd.get('name')||'나').trim(),gender:fd.get('gender'),calendar_type:fd.get('calendar_type'),is_leap_month:fd.get('is_leap_month')==='true',year:+fd.get('year'),month:+fd.get('month'),day:+fd.get('day'),hour:unknown?0:+fd.get('hour'),minute:unknown?0:+fd.get('minute'),time_known:!unknown,country_code:fd.get('country_code'),country:fd.get('country_custom')||'',city:fd.get('city')||'',partner_gender:fd.get('partner_gender')||'M'} }
  function bindTimeUnknown(root=document){$$('[data-time-block]',root).forEach(block=>{$$('.time-choice-button',block).forEach(btn=>btn.addEventListener('click',()=>{const unknown=btn.dataset.timeSet==='unknown';$$('.time-choice-button',block).forEach(x=>x.classList.toggle('active',x===btn));const check=$('input[type="checkbox"]',block);if(check)check.checked=unknown;show($('[data-time-inputs-for]',block),!unknown);show($('.time-unknown-message',block),unknown)}))})}
