  function bindBirthPickers(root=document){$$('[data-open-birth-picker]',root).forEach(btn=>btn.addEventListener('click',()=>{const key=btn.dataset.openBirthPicker,panel=$(`[data-birth-picker-panel="${key}"]`);if(!panel)return;const parsed=parseDate($(`[data-birth-text="${key}"]`)?.value)||{year:2000,month:1,day:1};panel.dataset.month=parsed.month;panel.dataset.day=parsed.day;$('[data-picker-year]',panel).value=parsed.year;renderPicker(panel,key);show(panel,true)}));$$('[data-close-birth-picker]',root).forEach(b=>b.addEventListener('click',()=>show(b.closest('.birth-picker-modal'),false)));$$('[data-year-step]',root).forEach(b=>b.addEventListener('click',()=>{const panel=b.closest('.birth-picker-panel'),input=$('[data-picker-year]',panel);input.value=Math.max(1900,Math.min(2100,(+input.value||2000)+(+b.dataset.yearStep)))}));$$('[data-confirm-birth-picker]',root).forEach(b=>b.addEventListener('click',()=>{const modal=b.closest('.birth-picker-modal'),key=b.dataset.confirmBirthPicker,y=+$('[data-picker-year]',modal).value,m=+modal.dataset.month,d=+modal.dataset.day;$(`[data-birth-text="${key}"]`).value=`${y}.${String(m).padStart(2,'0')}.${String(d).padStart(2,'0')}`;show(modal,false);syncMainInputs()}))}
  function renderPicker(modal,key){const months=$('[data-picker-months]',modal),days=$('[data-picker-days]',modal);months.innerHTML=Array.from({length:12},(_,i)=>`<button type="button" data-month="${i+1}">${i+1}월</button>`).join('');const y=+$('[data-picker-year]',modal).value||2000,m=+modal.dataset.month||1,max=new Date(y,m,0).getDate();days.innerHTML=Array.from({length:max},(_,i)=>`<button type="button" data-day="${i+1}">${i+1}</button>`).join('');$$('[data-month]',months).forEach(b=>b.onclick=()=>{modal.dataset.month=b.dataset.month;renderPicker(modal,key)});$$('[data-day]',days).forEach(b=>b.onclick=()=>{modal.dataset.day=b.dataset.day;$$('[data-day]',days).forEach(x=>x.style.background=x===b?'#eee9ff':'#fff')})}
  function personFields(prefix,label='상대방',{removable=false}={}){const head=removable?`<div class="dynamic-person-head"><strong data-member-title>${esc(label)}</strong><button class="member-remove-button" type="button" data-remove-member aria-label="${esc(label)} 삭제"><span aria-hidden="true">×</span>삭제</button></div>`:'';return `<div class="dynamic-person form-grid" data-person-prefix="${esc(prefix)}">${head}<label>이름<input name="${prefix}_name" required placeholder="${esc(label)} 이름"></label><label>성별<select name="${prefix}_gender"><option value="F">여성</option><option value="M">남성</option></select></label><label>양력/음력<select name="${prefix}_calendar_type"><option value="solar">양력</option><option value="lunar">음력</option></select></label><label class="leap-field hidden" data-leap-for="${prefix}">윤달<select name="${prefix}_is_leap_month"><option value="false">평달</option><option value="true">윤달</option></select></label><label>생년월일<input name="${prefix}_birth" placeholder="1990.01.01" required></label><label>출생시간<input name="${prefix}_time" placeholder="12:00"></label><label>출생 국가<select name="${prefix}_country_code" class="country-select"><option value="KR">대한민국</option></select></label></div>`}
  function memberAddButton(attribute){return `<div class="member-add-row"><button type="button" class="ghost-button member-add-button" ${attribute}><span class="member-add-bunny" aria-hidden="true"><b>＋</b></span><span class="member-add-copy"><strong>구성원 추가</strong><small>새 사람의 출생정보를 입력해요</small></span><span class="member-add-arrow" aria-hidden="true">→</span></button></div>`}
  function nextMemberNumber(root,stem){pruneMemberUndoHistory();const prefixes=[...$$('.dynamic-person',root).map(card=>card.dataset.personPrefix||''),...memberUndoHistory.map(item=>item.card.dataset.personPrefix||'')],numbers=prefixes.filter(prefix=>prefix.startsWith(stem)).map(prefix=>Number(prefix.slice(stem.length))||0);return Math.max(0,...numbers)+1}
  function refreshMemberLabels(root){$$('.dynamic-person',root).forEach((card,i)=>{const label=`구성원 ${i+1}`,title=$('[data-member-title]',card),remove=$('[data-remove-member]',card);if(title)title.textContent=label;if(remove)remove.setAttribute('aria-label',`${label} 삭제`)})}
  function pruneMemberUndoHistory(){for(let i=memberUndoHistory.length-1;i>=0;i--){const item=memberUndoHistory[i];if(!item.parent.isConnected||item.card.isConnected)memberUndoHistory.splice(i,1)}return memberUndoHistory.length}
  function showMemberUndoToast(message='구성원을 삭제했습니다.'){const count=pruneMemberUndoHistory();if(!count){toast(message);return}const copy=count>1?`${message} 최근 삭제부터 ${count}건을 되돌릴 수 있어요.`:message;toast(copy,{actionLabel:count>1?`되돌리기 (${count})`:'되돌리기',duration:8000,onAction:undoLastMemberRemoval})}
  function undoLastMemberRemoval(){pruneMemberUndoHistory();const item=memberUndoHistory.pop();if(!item)return;const {card,parent,next,index,root,minimum,onChange}=item,positionAnchor=$$('.dynamic-person',parent)[index]||null;parent.insertBefore(card,next?.parentElement===parent?next:positionAnchor);refreshMemberLabels(root);bindMemberRemoval(root,{minimum,onChange});onChange();card.scrollIntoView({behavior:'smooth',block:'nearest'});const remaining=pruneMemberUndoHistory();if(remaining)showMemberUndoToast(`구성원을 복구했습니다. 이전 삭제 ${remaining}건이 남아 있어요.`);else toast('삭제한 구성원을 다시 복구했습니다.')}
  function bindMemberRemoval(root,{minimum=1,onChange=()=>{}}={}){$$('[data-remove-member]',root).forEach(button=>{button.onclick=()=>{const cards=$$('.dynamic-person',root);if(cards.length<=minimum){toast('그룹에는 나를 제외하고 최소 한 명이 필요해요.');return}const card=button.closest('.dynamic-person'),next=card?.nextElementSibling,parent=card?.parentElement,index=cards.indexOf(card);if(!card||!parent)return;card.remove();memberUndoHistory.push({card,parent,next,index,root,minimum,onChange});refreshMemberLabels(root);onChange();showMemberUndoToast()}})}
