  function updateOptions(){const f=$('#profileForm'),match=f.elements.build_matches.checked,pair=f.elements.include_pair.checked,group=f.elements.include_group.checked;$$('.option-card',f).forEach(x=>x.classList.toggle('selected',$('input',x).checked));show($('#matchOptionFields'),match);const pairRoot=$('#initialPairFields'),groupRoot=$('#initialGroupFields');show(pairRoot,pair);show(groupRoot,group);if(pair&&!pairRoot.innerHTML)pairRoot.innerHTML=`<h3>함께 볼 한 사람</h3>${personFields('pair','상대방')}<label class="compact-label">관계 유형<select name="pair_mode"><option value="love">연인</option><option value="friend">친구</option></select></label>`;if(group&&!groupRoot.innerHTML)groupRoot.innerHTML=`<h3>함께 볼 그룹</h3><label class="compact-label">그룹 유형<select name="group_context"><option value="friends">친구</option><option value="work">직장·프로젝트</option><option value="family">가족</option><option value="hobby">취미 모임</option></select></label><div data-initial-members>${personFields('member1','멤버 1',{removable:true})}${personFields('member2','멤버 2',{removable:true})}</div>${memberAddButton('data-add-initial-member')}`;$$('input,select',pairRoot).forEach(x=>x.disabled=!pair);$$('input,select',groupRoot).forEach(x=>x.disabled=!group);bindCalendarControls(f);bindCountryControls(f);refreshMemberLabels(groupRoot);bindMemberRemoval(groupRoot,{onChange:updateEstimate});const addButton=$('[data-add-initial-member]');if(addButton)addButton.onclick=addInitialMember;updateEstimate()}
