  function pairFormHtml(){return `<div class="page-shell">${section('1:1 궁합 새로 보기',`<form id="pairForm" class="form-grid"><input type="hidden" name="mode" value="love">${personFields('target','상대방')}<label>관계 유형<select name="mode"><option value="love">연인</option><option value="friend">친구</option></select></label><button class="primary-button wide" type="submit">두 사람 궁합 보기</button></form>`)}</div>`}
  function bindPairForm(){const f=$('#pairForm');if(!f)return;bindCalendarControls(f);bindCountryControls(f);f.onsubmit=submitPair}
  async function submitPair(e){e.preventDefault();if(!state.profile){toast('먼저 내 사주 리포트를 만들어 주세요.');return}try{const fd=new FormData(e.currentTarget),target=profileFromPrefix(fd,'target');state.pair=await postWithProgress('pair','/api/pair',{user:state.profile,target,mode:fd.get('mode')},{people:2});renderPair()}catch(err){toast(err.message)}}
  function starPositionText(row){return list(row?.positions).join(' · ')||row?.position||''}
