  function groupMemberFacts(data,r){const candidates=[r.member_facts,data?.members,data?.member_facts,state.group?.members,state.result?.initial_group?.members];return candidates.find(rows=>list(rows).length)||[]}
  function groupNetworkHtml(r,data){const facts=groupMemberFacts(data,r),byName=new Map(list(facts).map(row=>[row?.profile?.name,row]));return `<div class="group-network" data-group-selection-status="전체 구성원 보기">${list(r.names).map((name,i)=>{const fact=facts[i]||byName.get(name)||{},pillar=fact?.chart?.day_pillar||'일주 확인 필요',meta=pillarMeta(pillar);return `<button class="group-node" data-group-node="${i}" type="button"><strong>${esc(name)}</strong><span>${esc(pillar)}</span><small>${esc(meta.reading)} · ${esc(meta.elements)}</small></button>`}).join('')}</div>`}
  function groupPersonInspector(r,index){const name=r.names?.[index],role=list(r.roles).find(x=>x.name===name)||{},isAnchor=r.anchor?.name===name||r.anchor===name,isBridge=r.bridge?.name===name||r.bridge===name,average=role.average_connection??role.average_score;return `<div id="groupPersonInspector"><div class="inspector-title"><div><span class="eyebrow">구성원 역할</span><h3>${esc(name)}</h3></div>${average!=null?`<strong>${Math.round(average)}점</strong>`:''}</div><div class="tag-list">${isAnchor?'<span class="tag">중심축</span>':''}${isBridge?'<span class="tag">연결자</span>':''}${role.role?`<span class="tag">${esc(role.role)}</span>`:''}</div>${infoCard('이 역할이 잘 맞는 이유',role.role_reason||role.reason)}${infoCard('함께할 때의 사용법',role.role_guide||role.guide)}${infoCard('주의할 점',role.caution)}</div>`}
  function groupPairInspector(r,pair){const aName=pair?.a??pair?.name_a,bName=pair?.b??pair?.name_b,report=pair?.report||{},analysis=report.analysis||{},score=pair?.score??report.score??0;return `<div id="groupPairInspector"><div class="inspector-title"><div><span class="eyebrow">두 사람의 연결</span><h3>${esc(aName)} × ${esc(bName)}</h3></div><strong>${Math.round(score)}점</strong></div><p class="inspector-lead">${rich(text(report.overview)||pair?.label||'두 사람의 관계 흐름을 정리했습니다.')}</p><div class="detail-grid">${infoCard('잘 맞는 점',report.strengths)}${infoCard('조율할 점',report.risks)}${infoCard('대화 방법',analysis.communication||analysis.communication_daily)}${infoCard('역할을 나누는 방법',analysis.role_split)}${infoCard('엇갈리기 쉬운 장면',analysis.friction_scene)}${infoCard('관계를 활용하는 법',pair?.advice||analysis.fit)}</div>${pair?.day_pillar_relation?`<p class="method-footnote">${rich(pair.day_pillar_relation)}</p>`:''}</div>`}
  function bindGroupInteractions(root,r){const box=$('.group-network',root);$$('[data-group-node]',root).forEach(btn=>{const run=()=>{$$('[data-group-node]',root).forEach(x=>x.classList.toggle('active',x===btn));$('#groupInspector').innerHTML=groupPersonInspector(r,+btn.dataset.groupNode)};btn.onclick=run;btn.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();run()}})});$$('[data-matrix-pair]',root).forEach(btn=>{const run=()=>{$('#groupInspector').innerHTML=groupPairInspector(r,list(r.pairwise)[+btn.dataset.matrixPair])};btn.onclick=run;btn.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();run()}})});root.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#groupInspector').innerHTML='<p>구성원이나 관계 점수를 선택해 자세히 살펴보세요.</p>';$$('.active',box).forEach(x=>x.classList.remove('active'))}});if(list(r.pairwise).length)$('#groupInspector').innerHTML=groupPairInspector(r,list(r.pairwise)[0])}
  function groupMetric(label,value,detail=''){if(value==null||value==='')return '';const pairName=typeof value==='object'&&value.a&&value.b?`${value.a} × ${value.b}`:'',name=typeof value==='object'?(value.name||pairName||value.label):value,context=detail||(pairName&&value.label?value.label:''),score=typeof value==='object'?(value.score??value.average_score??value.average):null;return `<article class="metric-card"><span>${esc(label)}</span><strong>${esc(name)}</strong>${score!=null?`<b>${Math.round(score)}점</b>`:''}${context?`<p>${rich(context)}</p>`:''}</article>`}
  function matrixTone(score){return score>=80?'excellent':score>=70?'good':score>=60?'balanced':score>=50?'caution':'friction'}
  function groupedRoleCards(roles=[]){const groups=new Map();list(roles).forEach(row=>{const key=row.role||'추천 역할';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(row)});return `<div class="role-grid grouped-roles">${[...groups].map(([role,people])=>{const guideRow=people.find(x=>x.role_guide||x.guide)||{},guide=guideRow.role_guide||guideRow.guide||'이 역할이 필요한 장면과 책임 범위를 먼저 합의해 주세요.';return `<article class="role-card grouped-role"><div class="role-card-head"><span>${people.length}명</span><h3>${esc(role)}</h3></div><div class="role-people">${people.map(person=>`<span>${esc(person.name)}${person.is_anchor?' · 중심축':''}${person.is_bridge?' · 연결자':''}</span>`).join('')}</div><p>${rich(guide)}</p></article>`}).join('')}</div>`}
  function renderGroup(data=state.group||state.result?.initial_group){const root=$('#page-group');if(!data){root.innerHTML=groupFormHtml();bindGroupForm();return}const r=data.analysis||{},names=list(r.names),matrix=r.matrix,pairs=list(r.pairwise);const matrixHtml=matrix?`<div class="matrix-legend" aria-label="관계 점수 색상 기준"><span><i class="friction"></i>조율 필요</span><span><i class="caution"></i>차이 있음</span><span><i class="balanced"></i>균형</span><span><i class="good"></i>잘 맞음</span><span><i class="excellent"></i>매우 잘 맞음</span></div><div class="matrix-wrap"><table class="group-matrix"><thead><tr><th>이름</th>${names.map(n=>`<th>${esc(n)}</th>`).join('')}</tr></thead><tbody>${names.map((n,i)=>`<tr><th>${esc(n)}</th>${names.map((_,j)=>{if(i===j)return '<td class="matrix-self">—</td>';const pairIndex=pairs.findIndex(p=>(p.a===n&&p.b===names[j])||(p.b===n&&p.a===names[j])),score=Math.round(Number(matrix[i]?.[j])||0);return `<td>${pairIndex>=0?`<button class="matrix-score ${matrixTone(score)}" type="button" data-matrix-pair="${pairIndex}" aria-label="${esc(n)}와 ${esc(names[j])} 관계 ${score}점 자세히"><strong>${score}</strong><small>점</small></button>`:'—'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`:'';const clusters=list(r.clusters);root.innerHTML=`<div class="page-shell"><section class="hero-summary card"><div><span class="eyebrow">GROUP MAP</span><h2>${esc(r.context_label||'그룹 관계')}</h2><p>${rich(r.summary||r.context_note||groupResultCopy(r.context))}</p>${tags(r.key_points)}</div><div class="score-ring" style="--score:${r.group_score||0}%"><strong>${Math.round(r.group_score||0)}</strong></div></section><div class="group-metrics">${groupMetric('가장 자연스러운 연결',r.strongest_pair)}${groupMetric('조율이 필요한 연결',r.weakest_pair)}${groupMetric('그룹 중심축',r.anchor)}${groupMetric('사이를 잇는 사람',r.bridge)}</div>${section('관계 한눈에 보기',`<p class="section-guide">구성원을 누르면 실제 일주와 역할을, 표의 색상 점수를 누르면 두 사람의 강점·조율점·대화법을 확인할 수 있어요.</p>${groupNetworkHtml(r,data)}<div id="groupInspector" class="inspector"><p>구성원이나 관계 점수를 선택해 자세히 살펴보세요.</p></div>`)}${section('관계 매트릭스',matrixHtml||'<p>관계 점수를 표시할 자료가 없습니다.</p>')}${section('역할별 구성원',`<p class="section-guide">같은 역할은 한 번만 설명하고, 해당 역할이 어울리는 구성원을 함께 묶었습니다.</p>${groupedRoleCards(r.roles)}`)}${section('이 그룹을 편하게 운영하는 법',`${list(r.team_actions).length?listHtml(r.team_actions,'team-action-list'):'<p>구성원마다 편한 피드백 방식을 먼저 합의해 보세요.</p>'}${clusters.length?`<div class="cluster-grid">${clusters.map((c,i)=>infoCard(c.title||`관계 묶음 ${i+1}`,c.summary||c.members||c)).join('')}</div>`:''}${infoCard('그룹 해석 가이드',r.guide||r.context_note)}<p class="method-footnote">${rich(r.time_accuracy?.description||'그룹 점수는 관계의 우열이 아니라 역할 분담과 소통 방식을 살펴보기 위한 참고값입니다.')}</p><button class="ghost-button" type="button" data-group-jump="top">맨 위로</button>`)}</div>`;bindGroupInteractions(root,r);$('[data-group-jump]',root)?.addEventListener('click',()=>scrollTo({top:0,behavior:'smooth'}))}
  function groupFormHtml(){return `<div class="page-shell">${section('그룹 궁합 새로 보기',`<form id="groupForm"><label class="compact-label">그룹 유형<select name="context"><option value="friends">친구</option><option value="work">직장·프로젝트</option><option value="family">가족</option><option value="hobby">취미 모임</option></select></label><div data-group-members>${personFields('group1','멤버 1',{removable:true})}${personFields('group2','멤버 2',{removable:true})}</div>${memberAddButton('data-add-group')}<div class="group-submit-row"><button class="primary-button" type="submit">그룹 관계 보기</button></div></form>`)}</div>`}
  function bindGroupForm(){const f=$('#groupForm');if(!f)return;const root=$('[data-group-members]',f);bindCalendarControls(f);bindCountryControls(f);refreshMemberLabels(root);bindMemberRemoval(root);$('[data-add-group]',f).onclick=()=>{const n=nextMemberNumber(root,'group');root.insertAdjacentHTML('beforeend',personFields(`group${n}`,`구성원 ${$$('.dynamic-person',root).length+1}`,{removable:true}));const card=root.lastElementChild;bindCalendarControls(card);bindCountryControls(card);refreshMemberLabels(root);bindMemberRemoval(root)};f.onsubmit=submitGroup}
  async function submitGroup(e){e.preventDefault();try{const fd=new FormData(e.currentTarget),root=$('[data-group-members]',e.currentTarget),members=memberProfiles(fd,root);if(state.profile)members.unshift(state.profile);state.group=await postWithProgress('group','/api/group',{members,context:fd.get('context')},{members:members.length});renderGroup()}catch(err){toast(err.message)}}
  function evidenceBar(row,fallbackKey=''){const name=row.label||row.name||ELEMENT_LABEL[row.element||fallbackKey]||row.element||fallbackKey,value=Number(row.percent??row.value??0);return `<article class="evidence-bar-card"><div><strong>${esc(name)}</strong><span>${value.toFixed(1)}%</span></div><div class="evidence-track"><span style="width:${Math.max(0,Math.min(100,value))}%"></span></div><p>${rich(row.explanation||row.description||row.state||'이 비율은 성격의 우열이 아니라 어떤 역할이 반복되기 쉬운지를 보여줍니다.')}</p></article>`}
  function glossaryCards(rows={}){return `<div class="glossary-grid">${Object.entries(rows).map(([term,row])=>`<article><span>${esc(row.reading||'용어')}</span><h3>${esc(term)}</h3><p>${rich(row.plain||'')}</p><details><summary>조금 더 알아보기</summary><p>${rich(row.detail||'')}</p></details></article>`).join('')}</div>`}
  function starEvidenceCard(row={}){const name=row.name||row.label||row.title||'보조 기운',positions=starPositionText(row)||'원국 전체',tone=row.tone||'neutral';return `<article class="star-evidence-card ${esc(tone)}"><div class="star-evidence-head"><div><span>${esc(row.category||'보조 기운')}</span><h3>${esc(name)}</h3></div><b>${esc(positions)}</b></div><div class="star-meaning-block"><strong>무슨 뜻인가요?</strong><p>${rich(row.meaning||'전체 사주와 함께 참고하는 전통적인 보조 해석입니다.')}</p></div><div class="star-meaning-block practical"><strong>나에게 적용해서 보면</strong><p>${rich(row.practical||row.personal_note||'실제 생활에서 반복되는 장면이 있는지 확인해 보세요.')}</p></div>${row.personal_note&&row.personal_note!==row.practical?`<details><summary>내 원국과 연결한 상세 설명</summary><div><p>${rich(row.personal_note)}</p>${row.position_context?`<p>${rich(row.position_context)}</p>`:''}</div></details>`:row.position_context?`<small>${rich(row.position_context)}</small>`:''}</article>`}
  function renderDetails(){const r=state.result,p=r.profile_local||{},f=r.facts||{},elements=list(p.elements),tenGods=list(p.ten_gods),stars=list(p.special_stars||p.chart_detail?.stars),relations=list(p.self_relations||p.chart_detail?.relations);const elementRows=elements.length?elements:Object.entries(f.element_percent||{}).map(([element,percent])=>({element,percent})),relationCards=relations.map((x,i)=>typeof x==='string'?infoCard(`원국 내부 관계 ${i+1}`,x):infoCard(x.label||x.name||x.title,x.explanation||x.meaning||x.summary||x.description)),starCards=stars.map(starEvidenceCard);$('#page-details').innerHTML=`<div class="page-shell">${section('해석 근거를 쉽게 읽는 법',`<div class="evidence-guide"><strong>메인 리포트의 쉬운 생활 해설이 어디에서 나왔는지 확인하는 화면입니다.</strong><p>전문 용어 자체를 성격으로 단정하지 않고, 여러 항목을 함께 보아 반복되는 생활 패턴으로 바꿔 설명합니다.</p></div>${reportNatalChart(f,p.chart_detail||{})}<details class="technical-detail"><summary>네 기둥의 구조를 더 자세히 보기</summary>${chartDetailHtml(p.chart_detail||{})}</details>`)}${section('오행 구성과 생활 의미',`<p class="section-guide">비율이 높고 낮다는 것은 좋고 나쁨이 아니라, 자주 쓰는 방식과 덜 쓰는 방식을 구분하기 위한 자료입니다.</p><div class="evidence-grid">${elementRows.map(x=>evidenceBar(x,x.element)).join('')}</div>`)}${tenGods.length?section('십성 · 반복되는 역할 방식',`<p class="section-guide">십성은 성격 딱지가 아니라 자기주도·표현·현실관리·책임·학습처럼 반복되는 역할을 분류한 근거입니다.</p><div class="evidence-grid">${tenGods.map(x=>evidenceBar(x,x.name)).join('')}</div>`):''}${section('신살 · 길성 뜻풀이',`<p class="section-guide">신살 하나로 성격이나 미래를 단정하지 않습니다. 각 이름의 기본 뜻과 실제 생활에서 확인할 장면을 함께 읽어 주세요.</p><div class="star-evidence-grid">${starCards.join('')||'<div class="empty-state">현재 출생정보에서 별도로 강조되는 신살·길성이 없습니다.</div>'}</div>`)}${relations.length?section('원국 내부 관계',`<p class="section-guide">여러 기운이 서로 만날 때 반복되기 쉬운 반응을 보조적으로 설명합니다.</p><div class="detail-grid">${relationCards.join('')}</div>`):''}${Object.keys(r.glossary||{}).length?section('용어 사전',glossaryCards(r.glossary)):''}${section('자료 범위와 주의사항',`<div class="method-note">${sourceBadge(p.source_status||{})}<p>${rich(p.time_accuracy?.description||'출생시간 확인 범위에 따라 시주 관련 세부 항목은 달라질 수 있습니다.')}</p><p>${rich(r.notice||'사주명리는 전통 해석 체계에 따른 참고 자료입니다.')}</p></div>`)}</div>`}
  function renderAll(){renderProfile();renderFortune();renderAuto();renderPair();renderGroup();renderDetails();$('#workspaceTitle').textContent=`${state.profile?.name||'나'}의 사주 리포트`;switchPage('profile')}
  function switchPage(name){state.activePage=name;$$('.page').forEach(x=>x.classList.toggle('active',x.id===`page-${name}`));$$('.nav-button').forEach(x=>x.classList.toggle('active',x.dataset.page===name));scrollTo({top:0,behavior:'smooth'})}
  function fillMain(p){const f=$('#profileForm');for(const k of ['name','gender','calendar_type','country_code','partner_gender'])if(f.elements[k]&&p[k]!=null)f.elements[k].value=p[k];$('[data-birth-text="main"]').value=`${p.year}.${String(p.month).padStart(2,'0')}.${String(p.day).padStart(2,'0')}`;$('[data-time-text="main"]').value=p.time_known===false?'':`${String(p.hour||0).padStart(2,'0')}:${String(p.minute||0).padStart(2,'0')}`;if(p.time_known===false)$$('.time-choice-button',$('[data-time-block="main"]'))[1].click();syncMainInputs()}
  function fillPrefix(prefix,p){const f=$('#profileForm');for(const k of ['name','gender','calendar_type']){const e=f.elements[`${prefix}_${k}`];if(e)e.value=p[k]}if(f.elements[`${prefix}_birth`])f.elements[`${prefix}_birth`].value=`${p.year}.${String(p.month).padStart(2,'0')}.${String(p.day).padStart(2,'0')}`;if(f.elements[`${prefix}_time`])f.elements[`${prefix}_time`].value=p.time_known===false?'':`${String(p.hour||0).padStart(2,'0')}:${String(p.minute||0).padStart(2,'0')}`}
  function applyTestFixture(){const node=$('#testFixtureData');if(!node)return;const f=JSON.parse(node.textContent);fillMain(f.profile);const form=$('#profileForm');form.elements.build_matches.checked=!!f.build_matches;form.elements.include_pair.checked=!!f.pair;form.elements.include_group.checked=!!f.group;updateOptions();if(f.pair)fillPrefix('pair',f.pair.profile);if(f.group){const root=$('[data-initial-members]');root.innerHTML='';f.group.members.forEach((p,i)=>{root.insertAdjacentHTML('beforeend',personFields(`member${i+1}`,`멤버 ${i+1}`,{removable:true}));fillPrefix(`member${i+1}`,p)});refreshMemberLabels(root);bindCalendarControls(root);bindCountryControls(root);bindMemberRemoval(root,{onChange:updateEstimate});form.elements.group_context.value=f.group.context}state.testFixtureApplied=true;toast('테스트 데이터를 입력했습니다.');updateEstimate()}
  function startFromIntro(){if(document.body.dataset.testMode==='true'&&!state.testFixtureApplied)applyTestFixture();showInputScreen({fromReport:false})}
  function initBunnyCursor(){const cursor=$('#bunnyCursor'),fine=matchMedia('(pointer:fine)');if(!cursor||!fine.matches)return;let boingTimer,scrollFrame,lastX=-80,lastY=-80;const interactive='a,button,input,textarea,select,summary,[role="button"],.option-card,[data-open-birth-picker],[data-page]',syncInteractive=target=>cursor.classList.toggle('is-interactive',target instanceof Element&&!!target.closest(interactive)),syncAtPointer=()=>syncInteractive(document.elementFromPoint(lastX,lastY));document.addEventListener('pointermove',e=>{lastX=e.clientX;lastY=e.clientY;cursor.style.left=`${lastX}px`;cursor.style.top=`${lastY}px`;cursor.classList.add('is-visible');syncInteractive(e.target)},{passive:true});document.addEventListener('scroll',()=>{cancelAnimationFrame(scrollFrame);scrollFrame=requestAnimationFrame(syncAtPointer)},{passive:true,capture:true});new MutationObserver(syncAtPointer).observe(document.body,{attributes:true,attributeFilter:['class']});document.addEventListener('pointerdown',()=>{cursor.classList.remove('is-boing');void cursor.offsetWidth;cursor.classList.add('is-boing');clearTimeout(boingTimer);boingTimer=setTimeout(()=>cursor.classList.remove('is-boing'),560)},{passive:true});document.addEventListener('pointerleave',()=>cursor.classList.remove('is-visible'));window.addEventListener('blur',()=>cursor.classList.remove('is-visible'))}
  async function loadCountries(){try{const c=await api('/api/config');$$('.country-select').forEach(sel=>{const value=sel.value;sel.innerHTML=c.countries.map(x=>`<option value="${esc(x.code)}">${esc(x.name)}</option>`).join('')+'<option value="OTHER">기타</option>';sel.value=value||'KR'})}catch{}}
  function init(){initBunnyCursor();bindBirthPickers();bindTimeUnknown();bindCalendarControls();bindCountryControls();$('#introStartButton').onclick=startFromIntro;$('#inputBackButton').onclick=returnFromInput;$('#profileForm').onsubmit=submitInitial;$$('.option-card input').forEach(x=>x.onchange=updateOptions);$$('[data-birth-text],[data-time-text]').forEach(x=>x.addEventListener('blur',updateEstimate));$('#quickTestFixtureButton')?.addEventListener('click',applyTestFixture);$('#cancelAnalysisButton').onclick=cancelActiveRequest;$('#resetButton').onclick=()=>showInputScreen({fromReport:true});$('#printButton').onclick=()=>print();$$('.nav-button').forEach(x=>x.onclick=()=>switchPage(x.dataset.page));loadCountries();updateOptions();setInputBackMode(false)}
  document.addEventListener('DOMContentLoaded',init);
